type DiagnosticIncidentProvider = {
  note(input: ExhaustedDiagnosticIncident): Promise<DiagnosticIncidentAdmissionResult>;
  claim(): Promise<DiagnosticIncidentWakeOffer | null>;
  offerForClaim(claimId: string): Promise<DiagnosticIncidentWakeOffer | null>;
  claimCurrent(claimId: string): Promise<boolean>;
  bindInput(claimId: string, inputId: string): Promise<boolean>;
  settle(input: {
    claimId: string;
    outcome: 'delivered' | 'confirmed-unsent' | 'ambiguous';
    diagnosticSessionId?: string;
    diagnosticConversationId?: string;
    wakeInputId?: string;
    wakeMessageId?: string;
  }): Promise<boolean>;
  bindChat(sessionId: string, conversationId: string): Promise<boolean>;
  retireMissingChat(claimId: string, sessionId: string, conversationId: string): Promise<boolean>;
  suppress(sourceSessionId: string, sourceConversationId: string): Promise<number>;
  resolve(incidentId: string, disposition: 'recovered' | 'failed' | 'user-action'): Promise<boolean>;
  recoverSource?(input: RecoveredDiagnosticIncidentInput): Promise<RecoveredDiagnosticIncidentResult | null>;
  snapshot(): Promise<DiagnosticIncidentSnapshot>;
};
let diagnosticIncidentProvider: DiagnosticIncidentProvider | null = null;

/** Main injects the durable incident ledger to preserve Bridge's no-connection-import boundary. */
export function setDiagnosticIncidentProvider(provider: DiagnosticIncidentProvider | null): void {
  diagnosticIncidentProvider = provider;
  if (provider) void dispatchDiagnosticIncidentWakeNow().catch(error =>
    logWarn('bridge: could not reconcile the durable diagnostic incident owner at startup — ' + (error instanceof Error ? error.message : String(error))));
}

type InputLedgerRow = Awaited<ReturnType<typeof listInputs>>[number];

let diagnosticDispatchFlight: Promise<void> | null = null;

function diagnosticWakeIncidentForInput(snapshot: DiagnosticIncidentSnapshot, inputId: string) {
  return snapshot.incidents.find(row => row.wakeInputId === inputId && row.status === 'claimed') ?? null;
}

async function reconcileDiagnosticWakeInput(inputId: string): Promise<boolean> {
  const provider = diagnosticIncidentProvider;
  if (!provider) return false;
  const snapshot = await provider.snapshot();
  const incident = diagnosticWakeIncidentForInput(snapshot, inputId);
  if (!incident) return false;
  const row = (await listInputs()).find(input => input.id === inputId);
  if (!row) return false;
  if (row.state === 'sent' && row.conversationId && row.messageId) {
    const session = row.deliveredSessionId
      ? await getSession(row.deliveredSessionId)
      : await findSessionByConversation(row.conversationId, { requireUnique: true });
    if (!session?.conversationId || session.conversationId !== row.conversationId) return false;
    if (!await provider.bindChat(session.id, row.conversationId)) return false;
    return provider.settle({
      claimId: incident.claimId!,
      outcome: 'delivered',
      diagnosticSessionId: session.id,
      diagnosticConversationId: row.conversationId,
      wakeInputId: inputId,
      wakeMessageId: row.messageId
    });
  }
  if (row.state === 'failed' || row.state === 'cancelled') {
    const confirmedUnsent = row.sendAuthorizedAt === undefined &&
      row.deliveredAt === undefined && row.messageId === undefined;
    return provider.settle({
      claimId: incident.claimId!,
      outcome: confirmedUnsent ? 'confirmed-unsent' : 'ambiguous',
      wakeInputId: inputId,
      ...(row.messageId ? { wakeMessageId: row.messageId } : {})
    });
  }
  return false;
}

async function reconcileDiagnosticWakeForConversation(conversationId: string): Promise<boolean> {
  const provider = diagnosticIncidentProvider;
  if (!provider) return false;
  const snapshot = await provider.snapshot();
  const inputIds = snapshot.incidents
    .filter(row => row.status === 'claimed' && row.wakeInputId)
    .map(row => row.wakeInputId!);
  if (!inputIds.length) return false;
  const rows = await listInputs();
  for (const inputId of inputIds) {
    const row = rows.find(item => item.id === inputId);
    if (row?.conversationId === conversationId && await reconcileDiagnosticWakeInput(inputId)) return true;
  }
  return false;
}

/**
 * Event-driven dispatcher for the one durable diagnostic owner.
 *
 * It reuses the ordinary session-input transport, so Send authorization, receipt ambiguity,
 * browser FIFO, Core enrollment and exact message ids keep their existing owners. No timer or
 * model request exists here: callers invoke this only after admission/startup/input receipts.
 */
async function dispatchDiagnosticIncidentWakeNow(): Promise<void> {
  if (diagnosticDispatchFlight) return diagnosticDispatchFlight;
  const flight = (async () => {
    const provider = diagnosticIncidentProvider;
    if (!provider || getConfig().ui.automationPaused === true || coreBrowserDispatchStopped()) return;
    const snapshot = await provider.snapshot();
    const claimed = snapshot.incidents.find(row => row.status === 'claimed' && row.claimedAt !== null);
    let offer = claimed?.claimId
      ? await provider.offerForClaim(claimed.claimId)
      : await provider.claim();
    if (!offer || !await provider.claimCurrent(offer.claimId)) return;
    const incidentId = offer.incidentId;
    const currentSnapshot = await provider.snapshot();
    const currentIncident = currentSnapshot.incidents.find(row => row.id === incidentId && row.status === 'claimed');
    if (!currentIncident) return;
    const inputId = currentIncident.wakeInputId ?? randomUUID();
    const existing = currentIncident.wakeInputId
      ? (await listInputs()).find(row => row.id === inputId)
      : undefined;
    if (existing) {
      if (await reconcileDiagnosticWakeInput(inputId)) void dispatchDiagnosticIncidentWakeNow();
      else if (['queued', 'browser'].includes(existing.state)) wakeBrowserWork();
      return;
    }

    let sessionId: string | null = null;
    if (offer.target.kind === 'reuse') {
      const target = await getSession(offer.target.sessionId);
      if (!target?.conversationId) {
        // A missing/damaged checkpoint is not permission to replace a diagnostic chat. Only the
        // session owner's positive directory-absence proof may retire this exact stale binding.
        if (!await sessionDirectoryMissing(offer.target.sessionId) ||
            !await provider.retireMissingChat(offer.claimId, offer.target.sessionId, offer.target.conversationId)) return;
        const refreshed = await provider.offerForClaim(offer.claimId);
        if (!refreshed || refreshed.target.kind !== 'create' || !await provider.claimCurrent(refreshed.claimId)) return;
        offer = refreshed;
      } else {
        if (target.activeTurnId || runningToolCalls(target.conversationId) > 0) return;
        if (target.conversationId !== offer.target.conversationId &&
            !await provider.bindChat(target.id, target.conversationId)) return;
        sessionId = target.id;
      }
    }
    // Do not reserve an input UUID until the reusable chat is actually idle and eligible. A
    // claimed incident without a bound input can be retried from the diagnostic chat's next
    // event boundary; a bound UUID must always name a real durable outbox row or a recoverable
    // enqueue attempt.
    if (!await provider.bindInput(offer.claimId, inputId)) return;
    // Source recovery or explicit Stop can settle the incident while the durable wake UUID is
    // being bound. Recheck before creating the outbox row so that event cannot manufacture a
    // diagnostic Send after its own authority has disappeared.
    if (!await provider.claimCurrent(offer.claimId)) return;
    try {
      await enqueueInput({
        id: inputId,
        sessionId,
        ...(sessionId === null ? { nickname: 'CoS Diagnostics' } : {}),
        text: offer.message,
        mode: 'auto',
        dueAt: Date.now(),
        // Diagnostics is another account-owned automatic chat, not permission to
        // inherit an arbitrary native picker left on Medium in a reusable tab.
        model: getConfig().multiAgent.defaultModel || null,
        reasoningEffort: getConfig().multiAgent.defaultReasoning || null,
        automation: 'off'
      });
      // enqueueInput is itself durable and can yield. If exact source recovery won during that
      // write, the row is still ownerless/queued because wakeBrowserWork has not run yet: cancel
      // it under the ordinary outbox owner rather than exposing a now-unneeded model turn.
      if (!await provider.claimCurrent(offer.claimId)) {
        await cancelInput(inputId);
        return;
      }
      wakeBrowserWork();
    } catch (error) {
      await provider.settle({ claimId: offer.claimId, outcome: 'confirmed-unsent', wakeInputId: inputId });
      logWarn('bridge: diagnostic incident ' + offer.incidentId + ' could not enter the durable input queue — ' + (error instanceof Error ? error.message : String(error)));
    }
  })().catch(() => {
    // This owner is also entered from fire-and-forget activity edges. A failed
    // strict ledger read must retain custody, not escape as an unhandled process
    // rejection or create a replacement incident/input. The next ordinary event
    // can retry through the same single-flight owner once durability is restored.
    logWarn('bridge: diagnostic wake reconciliation failed; retained incident and input custody; inspect diagnostic-incidents durability before retry');
  }).finally(() => {
    if (diagnosticDispatchFlight === flight) diagnosticDispatchFlight = null;
  });
  diagnosticDispatchFlight = flight;
  return flight;
}

async function reconcileRecoveredDiagnosticSource(
  input: RecoveredDiagnosticIncidentInput
): Promise<boolean> {
  const provider = diagnosticIncidentProvider;
  if (!provider?.recoverSource) return false;
  let recovered = await provider.recoverSource(input);
  if (!recovered) return false;
  if (recovered.resolved) {
    void dispatchDiagnosticIncidentWakeNow();
    return true;
  }
  const wakeInputId = recovered.incident.status === 'claimed' ? recovered.incident.wakeInputId : null;
  if (!wakeInputId) return false;
  const before = (await listInputs()).find(row => row.id === wakeInputId);
  if (before && (before.state === 'queued' ||
      (before.state === 'browser' && before.requiresAuthorization === true && before.sendAuthorizedAt === undefined))) {
    await cancelInput(wakeInputId);
  }
  const after = (await listInputs()).find(row => row.id === wakeInputId);
  const confirmedUnsent = !after || (after.state === 'cancelled' && after.sendAuthorizedAt === undefined &&
    after.deliveredAt === undefined && after.messageId === undefined);
  if (!confirmedUnsent) return false;
  recovered = await provider.recoverSource({ ...input, confirmedUnsentWakeInputId: wakeInputId });
  if (!recovered?.resolved) return false;
  void dispatchDiagnosticIncidentWakeNow();
  return true;
}

async function admitDiagnosticIncident(input: ExhaustedDiagnosticIncident): Promise<void> {
  const provider = diagnosticIncidentProvider;
  if (!provider) return;
  const admitted = await provider.note(input);
  if (admitted.accepted) await dispatchDiagnosticIncidentWakeNow();
}

async function resolveDiagnosticIncidentFromObservations(
  conversationId: string,
  recordedSessionId: string | null
): Promise<void> {
  const provider = diagnosticIncidentProvider;
  if (!provider || !recordedSessionId) return;
  let snapshot = await provider.snapshot();
  if (snapshot.chat?.sessionId !== recordedSessionId) return;
  // Superseded provider A is intentionally still recorded into the same durable session lineage
  // after Compact & Resume. That historical write proves session identity, not current provider
  // authority. Only the session's presently attached conversation may move the reusable
  // diagnostic binding or settle its result; otherwise a late A event could roll B back to A.
  const attached = await getSession(recordedSessionId);
  if (attached?.conversationId !== conversationId) return;
  if (snapshot.chat.conversationId !== conversationId) {
    // Compact & Resume changes only the provider conversation. The recorder has just durably
    // proven that this exact conversation belongs to the incumbent diagnostic local session, so
    // move that one existing diagnostic owner before reading a result from successor B. bindChat
    // retains the recursion/source-collision fences and refuses a different local session.
    if (!await provider.bindChat(recordedSessionId, conversationId)) return;
    snapshot = await provider.snapshot();
  }
  if (snapshot.chat?.conversationId !== conversationId) return;
  const incident = snapshot.incidents.find(row => row.status === 'delivered' && row.wakeMessageId);
  if (!incident || !snapshot.chat?.sessionId) return;
  // A reusable diagnostic chat necessarily contains old results. Resolve only from the turn
  // that starts after this incident's exact native wake user-message receipt. Stable session
  // first position, not a canonical message's latest revision cursor, is the causal fence across
  // reload/hydration. Metadata-only revisions cannot move an authored question across a turn.
  const history = await readEvents(snapshot.chat.sessionId, {
    kinds: ['user_message', 'turn_start', 'assistant_message']
  });
  const wake = history.find(event => event.kind === 'user_message' && event.messageId === incident.wakeMessageId);
  if (!wake) return;
  const wakePosition = positionOf(wake);
  const turn = history.find(event => event.kind === 'turn_start' && event.seq > wakePosition && event.turnId);
  if (!turn?.turnId) return;
  // Any later authored user message means the dedicated chat moved on before this incident
  // produced its result; do not attribute a later answer back to the older wake.
  const nextUser = history.find(event => event.kind === 'user_message' && positionOf(event) > wakePosition && event.messageId !== incident.wakeMessageId);
  const final = history.findLast(event =>
    event.kind === 'assistant_message' && event.final === true && event.turnId === turn.turnId &&
    // Terminal content must itself precede the next question. Its store-owned anchor survives
    // rendering-only revisions without accepting content that actually became final too late.
    // Legacy origin can be streaming prose, so absent terminal-content proof uses its latest seq.
    (event.finalContentSeq ?? event.seq) > turn.seq &&
    (!nextUser || (event.finalContentSeq ?? event.seq) < positionOf(nextUser)));
  if (!final || final.kind !== 'assistant_message') return;
  const match = /(?:^|\n)DIAGNOSTIC_RESULT:\s*(recovered|failed|user-action)\s*$/i.exec(final.message.text.trim());
  if (!match) return;
  await provider.resolve(incident.id, match[1]!.toLowerCase() as 'recovered' | 'failed' | 'user-action');
  void dispatchDiagnosticIncidentWakeNow();
}

/**
 * A direct authored input cannot attach Core until the existing plugin-refresh owner has
 * enrolled ChatGPT's exact app id. Keep that same input queued while the already-durable Core
 * enrollment request is actionable; never hand it to a page just to fail after opening a tab.
 */
function inputNeedsCoreEnrollment(row: InputLedgerRow): boolean {
  return userRequestedInput(row) && row.purpose !== 'decision' &&
    (row.state === 'queued' || (row.state === 'browser' && row.requiresAuthorization === true && row.sendAuthorizedAt === undefined));
}

async function demandedCoreRefresh(rows: InputLedgerRow[]): Promise<Awaited<ReturnType<typeof pendingPluginRefreshes>>[number] | null> {
  if (!rows.some(inputNeedsCoreEnrollment) || !pluginRefreshPublications().some(row => row.surface === 'core') ||
      await coreConnectorPresence()) return null;
  // A claimed Refresh can finish in ChatGPT after its first page receipt timed out. Keep that
  // exact row visible to the demanding input so the same settings page can observe completion;
  // plugin-refresh still refuses a second stale-schema click.
  return (await pendingPluginRefreshes({ includeClaimed: true })).find(row => row.surface === 'core') ?? null;
}

type PluginRefreshProjection = Awaited<ReturnType<typeof pendingPluginRefreshes>>[number];
function exactOperatorPluginRefresh(request: PluginRefreshProjection | undefined): request is PluginRefreshProjection & {
  operatorRearmReceipt: string;
  operatorRearmGeneration: number;
} {
  return Boolean(request?.surface === 'core' && request.appId &&
    typeof request.operatorRearmReceipt === 'string' && /^[a-f0-9-]{36}$/i.test(request.operatorRearmReceipt) &&
    Number.isSafeInteger(request.operatorRearmGeneration) && request.operatorRearmGeneration! > 0);
}

/**
 * A queued user send is allowed to wake the existing Core connection owner once when ChatGPT
 * has temporarily lost the exact app identity. This is deliberately input-scoped and cooldown
 * bound: it does not create a second connector, refresh owner, browser tab, or send attempt.
 * The durable input remains queued until the normal plugin-refresh owner proves the app id.
 */
const CORE_INPUT_RECOVERY_COOLDOWN_MS = 15_000;
let coreInputRecoveryAt = 0;
let coreInputRecoveryFlight: Promise<void> | null = null;

async function recoverCoreIdentityForInput(rows: InputLedgerRow[]): Promise<boolean> {
  if (!rows.some(inputNeedsCoreEnrollment)) return true;
  const connectionState = coreConnectionStateProvider?.();
  // An exact queued user input may wake Connection from transient offline health, not from a
  // user Disconnect or terminal setup/auth failure. Cached enrollment is not live transport.
  if (connectionState !== undefined && connectionState !== 'connected' && connectionState !== 'offline') return false;
  if (connectionState !== 'offline' && await coreConnectorPresence()) return true;
  // A current Core publication already has one exact enrollment owner. Reconnecting a healthy
  // Core endpoint cannot complete that provider-side receipt and would introduce competing work.
  if (pluginRefreshPublications().some(row => row.surface === 'core') &&
      (connectionState === undefined || connectionState === 'connected')) return false;
  const now = Date.now();
  const currentState = coreConnectionStateProvider?.();
  if (currentState !== undefined && currentState !== 'connected' && currentState !== 'offline') return false;
  if (!coreInputRecoveryFlight && coreConnectionRecoveryProvider &&
      now - coreInputRecoveryAt >= CORE_INPUT_RECOVERY_COOLDOWN_MS) {
    coreInputRecoveryAt = now;
    const flight = coreConnectionRecoveryProvider()
      .catch((error) => {
        logWarn(`bridge: queued input Core identity recovery failed — ${error instanceof Error ? error.message : String(error)}`);
      })
      .then(() => undefined);
    coreInputRecoveryFlight = flight;
    await flight;
    if (coreInputRecoveryFlight === flight) coreInputRecoveryFlight = null;
    // Connection may have republished the Core surface after the recovery call. Wake the
    // already-paired companion so its existing refresh poll can enroll the exact app id.
    wakeBrowserWork();
  } else if (coreInputRecoveryFlight) {
    await coreInputRecoveryFlight;
  }
  // A recovery promise's result cannot override Connection's newer authoritative state.
  const connector = await coreConnectorPresence();
  return !coreBrowserDispatchStopped() && Boolean(connector);
}
