        // lift an earlier human tab-close fence. A failed/timeout/stale Open never does.
        manuallyClosedTabAt.delete(conversation);
        try {
          await persistRecoveryFencesNow();
        } catch (err) {
          if (!manuallyClosedTabAt.has(conversation)) manuallyClosedTabAt.set(conversation, priorClose);
          void noteLocalIncident({
            source: 'app', reason: 'manual_close_release_not_durable',
            status: 'unresolved', conversationId: conversation, capture: 'not_requested',
            detail: err instanceof Error ? err.message : String(err),
            browserFacts: { errors: 1, runningTools: runningToolCalls(conversation),
              automationPaused: getConfig().ui.automationPaused === true }
          });
          logWarn(`bridge: could not persist explicit Open release for ${conversation} — ${err instanceof Error ? err.message : String(err)}`);
          return json(res, 503, { ok: false, error: 'manual_close_release_not_durable', retryable: true }, origin);
        }
        // A newer last-tab close can settle the same outstanding Open while the durable
        // release is writing. That later close wins; the old Chrome receipt grants nothing.
