    // An old frontend cannot revoke its replacement's switch or delivery custody.
    if (await conversationWasSuperseded(id)) return json(res, 409, { error: 'conversation_superseded' }, origin);
    const held = goalSwitchFor(id);
    await setGoalSwitchNow(id, held.mode, false);
    const failedInputs = await failInputsForDeletedConversation(id);
