    if (inputCloseGuard()) return manuallyClosedInput();
    const input = await claimBrowserInput(body.id, body.owner, target, body.requiresAuthorization === true, requestedProject);
    const claimedConnector = input && input.purpose !== 'decision' ? await coreConnectorPresence() : null;
