    const status: AckStatus = raw === 'attention' ? 'attention' : raw === 'deferred' ? 'deferred' : raw === 'failed' ? 'failed' : 'sent';
    const error = typeof body['error'] === 'string' ? body['error'].slice(0, 200) : null;
